const HTML_TEMPLATE = "<!DOCTYPE html>\n<html lang=\"uk\">\n<head>\n<meta charset=\"UTF-8\"/>\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, maximum-scale=1, minimum-scale=1, user-scalable=no, viewport-fit=cover\"/>\n<title>WWG QA Team · Embedded Media</title>\n<script async src=\"https://pay.google.com/gp/p/js/pay.js\"></script>\n<script src=\"https://accounts.google.com/gsi/client\" async defer></script>\n<script async src=\"https://static-na.payments-amazon.com/checkout.js\"></script>\n<style>\n*{box-sizing:border-box}\nhtml,body,#app{min-height:100%;margin:0}\nbody{background:#050505;color:#f3f4f6;font-family:Inter,Arial,sans-serif;-webkit-font-smoothing:antialiased}\nbutton,input,textarea{font:inherit}\nbutton{cursor:pointer}\nimg{max-width:100%}\n.shell{width:min(1160px,calc(100% - 24px));margin:0 auto}\n.top{border-bottom:1px solid #1f2937;background:#050505}\n.topin{min-height:74px;display:flex;align-items:center;justify-content:space-between;gap:16px}\n.brand{display:flex;align-items:center;gap:14px}\n.brand img{width:58px;height:58px;object-fit:contain;background:#0b0b0b;border:1px solid #262626;padding:2px}\n.brandtext{font-weight:900;letter-spacing:-.03em}\n.version{font-size:12px;color:#9ca3af}\n.hero{display:grid;grid-template-columns:1.05fr .95fr;gap:18px;padding:24px 0}\n.hero-copy h1{margin:0;font-size:clamp(34px,5vw,62px);line-height:.92;letter-spacing:-.07em}\n.hero-copy p{margin:12px 0 0;color:#9ca3af;line-height:1.55;font-size:17px;max-width:680px}\n.hero-photo{background:#0b0b0b;border:1px solid #202020;padding:12px;display:grid;place-items:center}\n.hero-photo img{width:100%;max-height:330px;object-fit:contain}\n.layout{display:grid;grid-template-columns:1.05fr .95fr;gap:16px;padding-bottom:24px}\n.col{display:grid;gap:16px}\n.card{background:#0b0b0b;border:1px solid #1f2937}\n.card-h{padding:16px 18px;border-bottom:1px solid #1f2937;background:#090909}\n.card-h h2,.card-h h3{margin:0;font-size:18px;letter-spacing:-.03em}\n.card-note{margin-top:6px;color:#9ca3af;font-size:14px;line-height:1.45}\n.card-b{padding:16px 18px}\n.grid2{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}\n.service{border:1px solid #1f2937;padding:12px;background:#060606;display:grid;gap:10px}\n.service strong{font-size:15px}\n.mini{font-size:13px;color:#9ca3af;line-height:1.45}\ninput,textarea{width:100%;min-height:42px;background:#050505;border:1px solid #374151;color:#f3f4f6;padding:10px 12px;outline:none}\ntextarea{min-height:96px;resize:vertical}\n.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}\n.row>*{flex:1}\n.row .btn{flex:0 0 auto}\n.btn{min-height:42px;border:1px solid #374151;background:#0b0b0b;color:#f3f4f6;padding:10px 14px;font-weight:800}\n.btn:hover{background:#111827}\n.btn.primary{background:#dc2626;border-color:#dc2626;color:#fff}\n.btn.primary:hover{background:#b91c1c}\n.btn.gpay{background:#050505;border-color:#6b7280;color:#fff}\n.btn.link{background:#00d66b;border-color:#00d66b;color:#04150d}\n.btn.phonepe{background:#6739b7;border-color:#6739b7;color:#fff}\n.btn.paytm{background:#00baf2;border-color:#00baf2;color:#06253b}\n.btn.playid{background:#1f2937;border-color:#374151}\n.btn.kbc{background:#0f4c81;border-color:#0f4c81;color:#fff}\n.pay-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}\n.gpay-box{border:1px solid #1f2937;background:#060606;padding:14px;display:grid;gap:10px}\n#gpayNative{min-height:46px;display:flex;align-items:center}\n.gpay-status{font-size:13px;color:#9ca3af;line-height:1.45}\n.media-frame{position:relative;width:100%;aspect-ratio:16/9;border:1px solid #1f2937;background:#000;overflow:hidden}\n.media-frame iframe{position:absolute;inset:0;width:100%;height:100%;border:0}\n.audio-panel{display:grid;gap:10px}\naudio{width:100%;filter:invert(1) hue-rotate(180deg)}\n.info-grid{display:grid;gap:10px}\n.info-row{display:grid;grid-template-columns:140px 1fr;gap:10px;font-size:14px}\n.info-row strong{color:#d1d5db}\n.signin-profile{display:none;border:1px solid #1f2937;background:#060606;padding:12px;margin-top:12px}\n.signin-profile.active{display:block}\n.signin-head{display:flex;align-items:center;gap:12px}\n.signin-head img{width:48px;height:48px;object-fit:cover;border:1px solid #374151}\n.signin-meta{font-size:14px;line-height:1.4}\n.preview{display:none;margin-top:12px;max-width:100%;max-height:220px;border:1px solid #1f2937;padding:8px;background:#050505;object-fit:contain}\n.clicker{display:grid;place-items:center;gap:12px;padding:20px;border:1px solid #1f2937;background:#060606}\n.clicker-num{font-size:52px;font-weight:900;line-height:1}\n.footer{padding:0 0 22px;color:#6b7280;font-size:13px;text-align:center}\n.helper{font-size:13px;color:#9ca3af;line-height:1.45}\n.notice{border:1px solid #374151;background:#060606;color:#d1d5db;padding:10px;font-size:13px;line-height:1.45}\n@media(max-width:980px){.hero,.layout{grid-template-columns:1fr}}\n@media(max-width:760px){.grid2,.pay-grid{grid-template-columns:1fr}.info-row{grid-template-columns:1fr}.topin{align-items:flex-start;flex-direction:column;padding:12px 0}}\n\n.amazon-box{border:1px solid #1f2937;background:#060606;padding:14px;display:grid;gap:10px}\n.amazon-config{display:grid;gap:8px}\n.amazon-config textarea{min-height:110px;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px}\n#AmazonPayButton{min-height:48px;display:flex;align-items:center}\n\n</style>\n</head>\n<body>\n<div id=\"app\">\n<header class=\"top\">\n  <div class=\"shell topin\">\n    <div class=\"brand\">\n      <img src=\"data:image/png;base64,\" alt=\"WWG\" id=\"wwgLogo\"/>\n      <div class=\"brandtext\">WWG QA Team · Embedded Media</div>\n    </div>\n    <div class=\"version\">v24-google-signin-fixed</div>\n  </div>\n</header>\n\n<main class=\"shell\">\n  <section class=\"hero\">\n    <div class=\"hero-copy\">\n      <h1>Black QA payment panel</h1>\n      <p>Google Pay TEST authorization, app redirects, embedded YouTube player і audio player прямо на сайті.</p>\n    </div>\n    <div class=\"hero-photo\">\n      <img src=\"data:image/png;base64,\" alt=\"WWG QA Team\"/>\n    </div>\n  </section>\n\n  <div class=\"layout\">\n    <div class=\"col\">\n      <section class=\"card\">\n        <div class=\"card-h\">\n          <h2>Google Pay</h2>\n          <div class=\"card-note\">TEST authorization через офіційний Google Pay API.</div>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"gpay-box\">\n            <button class=\"btn gpay\" id=\"gpayMain\">G Pay · authorize</button>\n            <div id=\"gpayNative\">Loading native Google Pay...</div>\n            <div class=\"row\">\n              <input id=\"gpayAmount\" value=\"12.00\" placeholder=\"Amount\"/>\n              <input id=\"gpayCurrency\" value=\"USD\" placeholder=\"Currency\"/>\n              <input id=\"gpayCountry\" value=\"US\" placeholder=\"Country\"/>\n            </div>\n            <div class=\"gpay-status\" id=\"gpayStatus\">Waiting for Google Pay SDK...</div>\n            <div class=\"notice\">Google Pay працює в TEST environment. Токен повертається в статусі/console, гроші не списуються.</div>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"card\">\n        <div class=\"card-h\">\n          <h2>Amazon Pay Sandbox</h2>\n          <div class=\"card-note\">Amazon Pay button через checkout.js. Private key не вставляється на фронт.</div>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"amazon-box\">\n            <div id=\"AmazonPayButton\">Amazon Pay button буде тут після рендера.</div>\n            <div class=\"amazon-config\">\n              <input id=\"amazonMerchantId\" placeholder=\"merchantId\" value=\"merchant_id\"/>\n              <input id=\"amazonPublicKeyId\" placeholder=\"publicKeyId\" value=\"SANDBOX-xxxxxxxxxx\"/>\n              <input id=\"amazonCurrency\" placeholder=\"ledgerCurrency\" value=\"USD\"/>\n              <input id=\"amazonAmount\" placeholder=\"estimatedOrderAmount\" value=\"109.99\"/>\n              <textarea id=\"amazonPayload\" placeholder=\"payloadJSON\">{&quot;webCheckoutDetails&quot;:{&quot;checkoutReviewReturnUrl&quot;:&quot;https://a.com/merchant-review-page&quot;},&quot;storeId&quot;:&quot;amzn1.application-oa2-client.8b5e45312b5248b69eeaStoreId&quot;,&quot;scopes&quot;:[&quot;name&quot;,&quot;email&quot;,&quot;phoneNumber&quot;,&quot;billingAddress&quot;]}</textarea>\n              <input id=\"amazonSignature\" placeholder=\"signature generated by backend\"/>\n              <button class=\"btn primary\" id=\"renderAmazonPay\">Render Amazon Pay</button>\n            </div>\n            <div class=\"notice\">`signature` потрібно генерувати на бекенді через Amazon Pay SDK. `privateKey` не можна класти у HTML/JS, бо його побачить будь-хто.</div>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"card\">\n        <div class=\"card-h\">\n          <h2>Cashier Desk</h2>\n          <div class=\"card-note\">Payment-кнопки без показу URL.</div>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"pay-grid\" id=\"paymentGrid\"></div>\n        </div>\n      </section>\n\n      <section class=\"card\">\n        <div class=\"card-h\">\n          <h2>App Redirect Checks</h2>\n          <div class=\"card-note\">Тільки app redirects, без web version.</div>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"grid2\" id=\"redirectGrid\"></div>\n        </div>\n      </section>\n\n      <section class=\"card\">\n        <div class=\"card-h\">\n          <h2>Media</h2>\n          <div class=\"card-note\">YouTube player і аудіо плеєр прямо на сторінці.</div>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"service\">\n            <strong>YouTube video</strong>\n            <div class=\"media-frame\">\n              <iframe\n                src=\"https://www.youtube.com/embed/PxmjpQmguNM\"\n                title=\"Champagne Coast player\"\n                allow=\"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share\"\n                allowfullscreen></iframe>\n            </div>\n          </div>\n\n          <div class=\"service\" style=\"margin-top:10px\">\n            <strong>Audio: На мертвой планете летает серый пепел</strong>\n            <div class=\"audio-panel\">\n              <audio id=\"audioPlayer\" controls preload=\"metadata\" src=\"data:audio/mpeg;base64,\"></audio>\n              <input id=\"audioUrl\" placeholder=\"Встав прямий audio URL: mp3 / ogg / wav\"/>\n              <div class=\"row\">\n                <button class=\"btn primary\" id=\"loadAudioUrl\">Load audio URL</button>\n                <input id=\"audioFile\" type=\"file\" accept=\"audio/*\"/>\n              </div>\n              <div class=\"mini\">Пісня вже вбудована в сайт. Також можна замінити її через прямий audio URL або локальний файл.</div>\n            </div>\n          </div>\n\n          <div class=\"service\" style=\"margin-top:10px\">\n            <strong>Other test links</strong>\n            <div class=\"grid2\" id=\"testLinkGrid\"></div>\n            <div class=\"row\" style=\"margin-top:12px\">\n              <input id=\"customTestUrl\" placeholder=\"Встав свою лінку\"/>\n              <button class=\"btn primary\" id=\"openCustomTest\">Open custom link</button>\n            </div>\n          </div>\n        </div>\n      </section>\n    </div>\n\n    <div class=\"col\">\n      \n      <section class=\"card\">\n        <div class=\"card-h\">\n          <h2>Google sign-in</h2>\n          <div class=\"card-note\">Офіційний Google Identity Services: g_id_onload + g_id_signin + callback.</div>\n        </div>\n        <div class=\"card-b\">\n          <div id=\"googleSignInMessage\" class=\"helper\">Google Sign-In очікує GOOGLE_CLIENT_ID...</div>\n\n          <div id=\"g_id_onload\"\n               data-client_id=\"__GOOGLE_CLIENT_ID__\"\n               data-callback=\"handleCredentialResponse\"\n               data-auto_prompt=\"false\">\n          </div>\n\n          <div class=\"g_id_signin\"\n               data-type=\"standard\"\n               data-size=\"large\"\n               data-theme=\"outline\"\n               data-text=\"signin_with\"\n               data-shape=\"rectangular\"\n               data-logo_alignment=\"left\">\n          </div>\n\n          <div id=\"googleSignInProfile\" class=\"signin-profile\">\n            <div class=\"signin-head\">\n              <img id=\"profilePicture\" alt=\"profile\"/>\n              <div class=\"signin-meta\">\n                <div id=\"profileName\"></div>\n                <div id=\"profileEmail\" class=\"helper\"></div>\n              </div>\n            </div>\n            <div class=\"row\" style=\"margin-top:12px\">\n              <button class=\"btn\" id=\"signOutBtn\">Sign out</button>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"card\">\n        <div class=\"card-h\">\n          <h2>Інформація про користувача</h2>\n          <div class=\"card-note\">Хост, IP, GEO, User-Agent.</div>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"info-grid\" id=\"userInfo\">\n            <div class=\"info-row\"><strong>Host</strong><span>Loading...</span></div>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"card\">\n        <div class=\"card-h\"><h2>Можливість додати фото</h2></div>\n        <div class=\"card-b\">\n          <input id=\"photoInput\" type=\"file\" accept=\"image/*\"/>\n          <img id=\"photoPreview\" class=\"preview\" alt=\"preview\"/>\n        </div>\n      </section>\n\n      <section class=\"card\">\n        <div class=\"card-h\"><h2>Поля для текста</h2></div>\n        <div class=\"card-b\">\n          <div class=\"grid2\">\n            <input id=\"textField1\" placeholder=\"Text field 1\"/>\n            <input id=\"textField2\" placeholder=\"Text field 2\"/>\n          </div>\n          <textarea id=\"textArea1\" placeholder=\"Text area\"></textarea>\n        </div>\n      </section>\n\n      <section class=\"card\">\n        <div class=\"card-h\"><h2>Clicker</h2></div>\n        <div class=\"card-b\">\n          <div class=\"clicker\">\n            <div class=\"clicker-num\" id=\"clickerCount\">0</div>\n            <button class=\"btn primary\" id=\"clickerBtn\">CLICK</button>\n          </div>\n        </div>\n      </section>\n    </div>\n  </div>\n\n  <div class=\"footer\">WWG QA Team · v20 embedded media</div>\n</main>\n</div>\n\n<script>\n(function(){\n\"use strict\";\nvar GOOGLE_CLIENT_ID=\"__GOOGLE_CLIENT_ID__\";\nvar clickerCount=0;\nvar paymentsClient=null;\n\nvar baseRequest={apiVersion:2,apiVersionMinor:0};\nvar allowedCardNetworks=[\"AMEX\",\"DISCOVER\",\"INTERAC\",\"JCB\",\"MASTERCARD\",\"VISA\"];\nvar allowedCardAuthMethods=[\"PAN_ONLY\",\"CRYPTOGRAM_3DS\"];\nvar tokenizationSpecification={type:\"PAYMENT_GATEWAY\",parameters:{gateway:\"example\",gatewayMerchantId:\"exampleGatewayMerchantId\"}};\nvar baseCardPaymentMethod={type:\"CARD\",parameters:{allowedAuthMethods:allowedCardAuthMethods,allowedCardNetworks:allowedCardNetworks}};\nvar cardPaymentMethod=Object.assign({},baseCardPaymentMethod,{tokenizationSpecification:tokenizationSpecification});\n\nvar payments=[\n  {name:\"Link\",label:\"Pay with Link\",cls:\"link\",url:\"https://pay.gopay-wallet.com/payment-200?orderNo=RSbeashqk3da&payType=1\"},\n  {name:\"PayTM\",label:\"PayTM\",cls:\"paytm\",url:\"https://pay.gopay-wallet.com/payment-200?orderNo=RSbeashqkg2b&payType=1\"},\n  {name:\"PhonePe\",label:\"PhonePe\",cls:\"phonepe\",url:\"https://pay.gopay-wallet.com/payment-200?orderNo=RSbeashqkg2b&payType=1\"},\n  {name:\"Play ID\",label:\"Play ID\",cls:\"playid\",url:\"\"},\n  {name:\"CBC / KBC\",label:\"CBC / KBC\",cls:\"kbc\",url:\"\"}\n];\n\nvar appRedirects=[\n  {name:\"Telegram\",app:\"tg://resolve?domain=nsqmarket\"},\n  {name:\"Viber\",app:\"viber://\"},\n  {name:\"WhatsApp\",app:\"whatsapp://send?text=hello\"},\n  {name:\"Instagram\",app:\"instagram://app\"},\n  {name:\"TikTok\",app:\"snssdk1233://\"},\n  {name:\"Facebook\",app:\"fb://profile\"},\n  {name:\"Дія\",app:\"diia://\"}\n];\n\nvar testLinks=[\n  {name:\"Web-QR\",label:\"Open Web-QR\",url:\"https://webqr.com/\"},\n  {name:\"Ninja-chat\",label:\"Open Ninja-chat\",url:\"https://ninja-chat-a6f8f.web.app/\"}\n];\n\nfunction el(id){return document.getElementById(id)}\nfunction openWeb(url){if(!url)return;window.open(url,\"_blank\",\"noopener,noreferrer\")}\nfunction openApp(url){if(!url)return;window.location.href=url}\nfunction setGpayStatus(text){el(\"gpayStatus\").textContent=text}\nfunction decodeJwtPayload(token){\n  try {\n    var part=token.split(\".\")[1];\n    var base64=part.replace(/-/g,\"+\").replace(/_/g,\"/\");\n    var json=decodeURIComponent(atob(base64).split(\"\").map(function(c){return \"%\" + (\"00\" + c.charCodeAt(0).toString(16)).slice(-2);}).join(\"\"));\n    return JSON.parse(json);\n  } catch(e) {\n    return null;\n  }\n}\n\nfunction getGooglePaymentsClient(){\n  if(paymentsClient===null){\n    paymentsClient=new google.payments.api.PaymentsClient({\n      environment:\"TEST\",\n      paymentDataCallbacks:{onPaymentAuthorized:onPaymentAuthorized}\n    });\n  }\n  return paymentsClient;\n}\n\nfunction getGoogleIsReadyToPayRequest(){\n  return Object.assign({},baseRequest,{allowedPaymentMethods:[baseCardPaymentMethod]});\n}\n\nfunction getGoogleTransactionInfo(){\n  var amount=el(\"gpayAmount\").value||\"12.00\";\n  return {\n    displayItems:[\n      {label:\"Subtotal\",type:\"SUBTOTAL\",price:(Math.max(0,Number(amount)-1)).toFixed(2)},\n      {label:\"Tax\",type:\"TAX\",price:\"1.00\"}\n    ],\n    countryCode:el(\"gpayCountry\").value||\"US\",\n    currencyCode:el(\"gpayCurrency\").value||\"USD\",\n    totalPriceStatus:\"FINAL\",\n    totalPrice:amount,\n    totalPriceLabel:\"Total\"\n  };\n}\n\nfunction getGooglePaymentDataRequest(){\n  var req=Object.assign({},baseRequest);\n  req.allowedPaymentMethods=[cardPaymentMethod];\n  req.transactionInfo=getGoogleTransactionInfo();\n  req.merchantInfo={merchantName:\"WWG QA Team Test Merchant\"};\n  req.callbackIntents=[\"PAYMENT_AUTHORIZATION\"];\n  return req;\n}\n\nfunction onPaymentAuthorized(paymentData){\n  return new Promise(function(resolve){\n    setTimeout(function(){\n      var token=paymentData.paymentMethodData && paymentData.paymentMethodData.tokenizationData ? paymentData.paymentMethodData.tokenizationData.token : \"\";\n      setGpayStatus(\"Google Pay authorized SUCCESS. Token preview: \"+String(token).slice(0,180)+\"...\");\n      console.log(\"Google Pay TEST paymentData\", paymentData);\n      resolve({transactionState:\"SUCCESS\"});\n    },400);\n  });\n}\n\nfunction addGooglePayButton(){\n  var container=el(\"gpayNative\");\n  container.innerHTML=\"\";\n  var client=getGooglePaymentsClient();\n  var button=client.createButton({onClick:onGooglePaymentButtonClicked,buttonColor:\"black\",buttonType:\"pay\"});\n  container.appendChild(button);\n}\n\nfunction onGooglePaymentButtonClicked(){\n  if(!(window.google&&google.payments&&google.payments.api)){\n    setGpayStatus(\"Google Pay SDK not loaded yet.\");\n    return;\n  }\n  getGooglePaymentsClient().loadPaymentData(getGooglePaymentDataRequest()).catch(function(err){\n    var message=err && err.statusMessage ? err.statusMessage : JSON.stringify(err);\n    setGpayStatus(\"Google Pay error: \"+message);\n    console.error(err);\n  });\n}\n\nfunction initGooglePay(){\n  var tries=0;\n  var wait=setInterval(function(){\n    tries++;\n    if(window.google && google.payments && google.payments.api){\n      clearInterval(wait);\n      getGooglePaymentsClient().isReadyToPay(getGoogleIsReadyToPayRequest())\n        .then(function(res){\n          if(res.result){\n            addGooglePayButton();\n            setGpayStatus(\"Google Pay ready.\");\n          } else {\n            el(\"gpayNative\").textContent=\"Google Pay isReadyToPay=false\";\n            setGpayStatus(\"Google Pay isReadyToPay=false.\");\n          }\n        })\n        .catch(function(err){\n          el(\"gpayNative\").textContent=\"Google Pay init error\";\n          setGpayStatus(\"Google Pay init error.\");\n          console.error(err);\n        });\n    }\n    if(tries>80){\n      clearInterval(wait);\n      el(\"gpayNative\").textContent=\"Google Pay SDK timeout\";\n      setGpayStatus(\"Google Pay SDK timeout.\");\n    }\n  },100);\n}\n\n\nfunction renderAmazonPay(){\n  var buttonBox=el(\"AmazonPayButton\");\n  if(!(window.amazon && amazon.Pay && amazon.Pay.renderButton)){\n    buttonBox.textContent=\"Amazon Pay SDK ще не завантажився.\";\n    return;\n  }\n  var merchantId=el(\"amazonMerchantId\").value.trim();\n  var publicKeyId=el(\"amazonPublicKeyId\").value.trim();\n  var currency=el(\"amazonCurrency\").value.trim()||\"USD\";\n  var amount=el(\"amazonAmount\").value.trim()||\"109.99\";\n  var payloadJSON=el(\"amazonPayload\").value.trim();\n  var signature=el(\"amazonSignature\").value.trim();\n\n  if(!merchantId || !publicKeyId || !payloadJSON || !signature){\n    buttonBox.textContent=\"Заповни merchantId, publicKeyId, payloadJSON і signature.\";\n    return;\n  }\n\n  try {\n    buttonBox.innerHTML=\"\";\n    amazon.Pay.renderButton(\"#AmazonPayButton\", {\n      merchantId: merchantId,\n      publicKeyId: publicKeyId,\n      ledgerCurrency: currency,\n      checkoutLanguage: \"en_US\",\n      productType: \"PayAndShip\",\n      placement: \"Cart\",\n      buttonColor: \"Gold\",\n      estimatedOrderAmount: { amount: amount, currencyCode: currency },\n      createCheckoutSessionConfig: {\n        payloadJSON: payloadJSON,\n        signature: signature,\n        algorithm: \"AMZN-PAY-RSASSA-PSS-V2\"\n      }\n    });\n    console.log(\"Amazon Pay button rendered\");\n  } catch(e) {\n    buttonBox.textContent=\"Amazon Pay render error: \"+e.message;\n    console.error(e);\n  }\n}\n\nfunction renderPayments(){\n  var box=el(\"paymentGrid\");\n  payments.forEach(function(item,idx){\n    var btn=document.createElement(\"button\");\n    btn.className=\"btn \" + item.cls;\n    btn.textContent=item.label;\n    btn.dataset.payment=String(idx);\n    box.appendChild(btn);\n  });\n}\n\nfunction renderRedirects(){\n  var box=el(\"redirectGrid\");\n  appRedirects.forEach(function(item,idx){\n    var card=document.createElement(\"div\");\n    card.className=\"service\";\n    card.innerHTML='<strong>'+item.name+'</strong><button class=\"btn primary\" data-app=\"'+idx+'\">Open app</button>';\n    box.appendChild(card);\n  });\n}\n\nfunction renderTestLinks(){\n  var box=el(\"testLinkGrid\");\n  testLinks.forEach(function(item,idx){\n    var card=document.createElement(\"div\");\n    card.className=\"service\";\n    card.innerHTML='<strong>'+item.name+'</strong><div class=\"mini\">'+item.label+'</div><button class=\"btn\" data-test=\"'+idx+'\">Open</button>';\n    box.appendChild(card);\n  });\n}\n\nfunction initGoogleSignIn(){\n  var msg=el(\"googleSignInMessage\");\n  if(!GOOGLE_CLIENT_ID){\n    msg.textContent=\"GOOGLE_CLIENT_ID не заданий. Додай його в Cloudflare env, щоб увійти у свій акаунт.\";\n    return;\n  }\n  msg.textContent=\"Google Sign-In ready.\";\n}\n\nwindow.handleCredentialResponse = function(response) {\n  var token = response && response.credential ? response.credential : \"\";\n  var userData = decodeJwtPayload(token);\n  if(!userData){\n    el(\"googleSignInMessage\").textContent=\"Google sign-in success, але JWT не декодувався.\";\n    return;\n  }\n\n  console.log(\"Google user data:\", userData);\n\n  el(\"profileName\").textContent = \"Привіт, \" + (userData.name || \"Google user\");\n  el(\"profileEmail\").textContent = \"Email: \" + (userData.email || \"\");\n  if(userData.picture) el(\"profilePicture\").src = userData.picture;\n  el(\"googleSignInProfile\").classList.add(\"active\");\n  el(\"googleSignInMessage\").textContent=\"Signed in successfully.\";\n};\n\nasync function loadUserInfo(){\n  try {\n    var res = await fetch(\"/api/context\");\n    var data = await res.json();\n    var rows = [\n      [\"Хост\", data.host || \"\"],\n      [\"IP\", data.ip || \"\"],\n      [\"GEO\", [data.country, data.region, data.city, data.colo].filter(Boolean).join(\" / \")],\n      [\"Юзер агент\", data.userAgent || \"\"]\n    ];\n    var box=el(\"userInfo\");\n    box.innerHTML=\"\";\n    rows.forEach(function(item){\n      var row=document.createElement(\"div\");\n      row.className=\"info-row\";\n      row.innerHTML=\"<strong>\"+item[0]+\"</strong><span>\"+(item[1]||\"\")+\"</span>\";\n      box.appendChild(row);\n    });\n  } catch(e) {\n    var box=el(\"userInfo\");\n    box.innerHTML='<div class=\"info-row\"><strong>Error</strong><span>'+e.message+'</span></div>';\n  }\n}\n\ndocument.addEventListener(\"click\",function(e){\n  var pay=e.target.closest(\"[data-payment]\");\n  if(pay){\n    var item=payments[Number(pay.dataset.payment)];\n    if(item && item.url) openWeb(item.url);\n    return;\n  }\n  var app=e.target.closest(\"[data-app]\");\n  if(app){\n    var item=appRedirects[Number(app.dataset.app)];\n    if(item && item.app) openApp(item.app);\n    return;\n  }\n  var test=e.target.closest(\"[data-test]\");\n  if(test){\n    var item=testLinks[Number(test.dataset.test)];\n    if(item && item.url) openWeb(item.url);\n    return;\n  }\n});\n\nel(\"gpayMain\").onclick=onGooglePaymentButtonClicked;\nel(\"openCustomTest\").onclick=function(){ openWeb(el(\"customTestUrl\").value.trim()); };\nel(\"photoInput\").onchange=function(e){\n  var file=e.target.files&&e.target.files[0];\n  if(!file)return;\n  var img=el(\"photoPreview\");\n  img.src=URL.createObjectURL(file);\n  img.style.display=\"block\";\n};\nel(\"audioFile\").onchange=function(e){\n  var file=e.target.files&&e.target.files[0];\n  if(!file)return;\n  var player=el(\"audioPlayer\");\n  player.src=URL.createObjectURL(file);\n  player.load();\n  player.play().catch(function(){});\n};\nel(\"loadAudioUrl\").onclick=function(){\n  var url=el(\"audioUrl\").value.trim();\n  if(!url)return;\n  var player=el(\"audioPlayer\");\n  player.src=url;\n  player.load();\n  player.play().catch(function(){});\n};\nel(\"clickerBtn\").onclick=function(){\n  clickerCount++;\n  el(\"clickerCount\").textContent=String(clickerCount);\n};\nel(\"signOutBtn\").onclick=function(){\n  if(window.google && google.accounts && google.accounts.id){\n    google.accounts.id.disableAutoSelect();\n  }\n  el(\"googleSignInProfile\").classList.remove(\"active\");\n  el(\"profileName\").textContent=\"\";\n  el(\"profileEmail\").textContent=\"\";\n  el(\"profilePicture\").removeAttribute(\"src\");\n  el(\"googleSignInMessage\").textContent=\"Signed out.\";\n};\nel(\"wwgLogo\").onclick=function(){\n  clickerCount++;\n  el(\"clickerCount\").textContent=String(clickerCount);\n};\n\nel(\"renderAmazonPay\").onclick=renderAmazonPay;\nrenderPayments();\nrenderRedirects();\nrenderTestLinks();\ninitGooglePay();\ninitGoogleSignIn();\nloadUserInfo();\n})();\n</script>\n</body>\n</html>";

export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    if (url.pathname === "/api/health") {
      return Response.json({ ok: true, version: "v24-google-signin-fixed", project: "WWG QA Team" });
    }

    if (url.pathname === "/api/context") {
      const cf = request.cf || {};
      return Response.json({
        host: url.host,
        ip: request.headers.get("cf-connecting-ip") || "",
        country: cf.country || request.headers.get("cf-ipcountry") || "",
        region: cf.region || "",
        city: cf.city || "",
        colo: cf.colo || "",
        userAgent: request.headers.get("user-agent") || ""
      });
    }

    const html = HTML_TEMPLATE.replaceAll("__GOOGLE_CLIENT_ID__", env.GOOGLE_CLIENT_ID || "");
    return new Response(html, {
      headers: {
        "content-type": "text/html; charset=UTF-8",
        "cache-control": "public, max-age=60"
      }
    });
  }
};
